A.cards("c10s1",[{"id": "g10-1-standard", "h": "10.1 · Read the evidence and complete the explanation", "c": ["c10-1-core"], "src": ["TB10:10.1"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">What a recovered core adds</h4><ul class=\"e2-note-points\"><li>A core preserves the order and thickness of actual sediment and volcanic layers. Rock type and structures constrain depositional conditions; fossils support environmental interpretation and correlation.</li><li>Appropriate volcanic minerals can supply isotopic ages. Comparing layer thickness with elapsed time estimates accumulation rate; neither a fossil photograph nor a depth sounding supplies all those measurements.</li><li>Oxygen and carbon isotope patterns can help reconstruct chemistry and climate. Interpret them with sample age and geological context.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Nodules and indirect measurements</h4><ul class=\"e2-note-points\"><li><mark class=\"e2-study-term\">Manganese precipitating from seawater</mark> can form rounded, metal-rich nodules on the deep seafloor. Sampling composition, mapping distribution and evaluating environmental effects are different tasks.</li><li>A satellite measures sea-surface height related to gravity; it does not optically photograph a deep abyssal plain. <mark class=\"e2-study-term\">Seismic reflection</mark> maps buried geometry, whereas drilling recovers material.</li></ul></section>", "examId": "exam2", "traps": ["Depth, samples and buried structure require different observations."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.1-p2-Im3.png", "alt": "Exploring Geology · 10.1 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p2-Im4.png", "alt": "Exploring Geology · 10.1 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p4-Im7.png", "alt": "Exploring Geology · 10.1 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p4-Im8.png", "alt": "Exploring Geology · 10.1 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p3-Im5.png", "alt": "Exploring Geology · 10.1 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p6-Im9.png", "alt": "Exploring Geology · 10.1 · PDF p6 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p6 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.1-p6-Im10.png", "alt": "Exploring Geology · 10.1 · PDF p6 · original course figure", "cap": "Exploring Geology · 10.1 · PDF p6 · original source figure, unchanged geometry"}]}]);
