A.cards("c10s2",[{"id": "g10-2-standard", "h": "10.2 · Read the evidence and complete the explanation", "c": ["c10-2-core"], "src": ["TB10:10.2"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Separate crust construction from hydrothermal circulation</h4><ul class=\"e2-note-points\"><li>Magma freezes as pillow basalt, dikes and deeper igneous rock; seawater circulates through fractures above hot rock. Hot vent water is not the same material as the magma heating it.</li><li>Dissolved metals and sulfur precipitate when hot vent fluid cools and mixes with seawater. This produces the dark mineral plume and chimney rather than combustion.</li><li><mark class=\"e2-study-term\">Chemical energy</mark> supports bacteria and the associated vent food web. Tube worms, clams, crabs and other organisms illustrate an ecosystem that does not require sunlight at the deep seafloor.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Read the source end members conditionally</h4><ul class=\"e2-note-points\"><li>The fast and slow ridge profiles compare magmatic supply, cooling and faulting. A deep axial rift is characteristic of the slow end member, not every spreading center.</li><li>The <mark class=\"e2-study-term\">carbonate compensation depth</mark> is a local preservation boundary, not the depth of the crust–mantle contact. Clay and silica-rich sediment can accumulate where carbonate dissolves.</li></ul></section>", "examId": "exam2", "traps": ["Spreading creates crust; circulating seawater builds a different mineral system."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.2-p2-Im2.png", "alt": "Exploring Geology · 10.2 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.2 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.2-p3-Im3.png", "alt": "Exploring Geology · 10.2 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.2 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.2-p4-Im4.png", "alt": "Exploring Geology · 10.2 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.2 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.2-p4-Im5.png", "alt": "Exploring Geology · 10.2 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.2 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.2-p5-Im7.png", "alt": "Exploring Geology · 10.2 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.2 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide09.png", "alt": "In-class Lecture 15 · slide 9 · original course figure", "cap": "In-class Lecture 15 · slide 9 · original source figure, unchanged geometry"}]}]);
