A.cards("c10s3",[{"id": "g10-3-standard", "h": "10.3 · Read the evidence and complete the explanation", "c": ["c10-3-core"], "src": ["TB10:10.3"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Keep the three map quantities separate</h4><ul class=\"e2-note-points\"><li>Depth colors show relief; sediment-thickness colors show accumulated cover; age colors show when the oceanic crust formed. <mark class=\"e2-study-term\">Read each legend anew</mark>.</li><li>An older plate has had time to cool and collect sediment, but a nearby major river can strongly increase sediment supply. Thin cover far from land does not uniquely identify young crust.</li><li>A blank or no-data patch represents unavailable information, not automatically shallow water, zero sediment or young crust.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Explain what survives on each plate</h4><ul class=\"e2-note-points\"><li>Spreading creates age bands on both sides of a ridge. Subduction can consume one side of an oceanic record, producing asymmetry.</li><li>The age limit printed on a supplied map describes that map and its source. Avoid turning an old legend into an unconditional claim that no older oceanic material exists anywhere.</li></ul></section>", "examId": "exam2", "traps": ["Compare three different maps instead of treating every color as the same measurement."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.3-p4-Im5.png", "alt": "Exploring Geology · 10.3 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.3-p3-Im3.png", "alt": "Exploring Geology · 10.3 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p3 · original source figure, unchanged geometry"}]}]);
L.EXAM2.topics.push({"id": "E2C10S3", "ch": 10, "title": "10.3 · Read ocean depth, sediment, and age maps", "sections": ["10.3"], "concepts": ["c10-3-core"], "sources": ["TB10:10.3"], "media": [{"kind": "img", "src": "animations/chapter10/source/10.3-p2-Im2.png", "alt": "Exploring Geology · 10.3 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.3-p5-Im6.png", "alt": "Exploring Geology · 10.3 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.3-p4-Im5.png", "alt": "Exploring Geology · 10.3 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.3-p3-Im3.png", "alt": "Exploring Geology · 10.3 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.3 · PDF p3 · original source figure, unchanged geometry"}], "standardChapter10": true});
A.mc("e2-c10-standard-3-check","c10-3-core","A sediment-thickness map has a white patch identified as insufficient data. What can you conclude about that patch?",["*Sediment thickness is not established by that map|The source explicitly marks an area where data are insufficient.", "Its sediment thickness must be exactly zero|Missing measurements do not establish a zero value.", "It must be the youngest oceanic crust|The blank is not an age measurement.", "It must expose continental granite above sea level|No-data shading does not identify that rock or elevation."],"Distinguish absence of evidence on a map from evidence that a quantity is absent.",["TB10:10.3"],{"examId": "exam2", "mock": false, "topics": ["E2C10S3"]});
A.mc("e2-c10-standard-3-visual","c10-3-core","Compare the sediment and age globes. Why is sediment thickness alone an incomplete clock for oceanic crust?",["*Supply from continents and rivers also affects thickness|The maps show strong sediment-source effects as well as age effects.", "All oceanic sediment accumulates at one fixed rate|The source describes important spatial differences.", "Age colors and sediment colors use the same units|They represent different measured quantities.", "Every thick deposit marks a modern spreading axis|The youngest ridge crust generally has little sediment."],"Time and sediment delivery both matter; the source maps measure different properties.",["TB10:10.3"],{"examId": "exam2", "mock": false, "topics": ["E2C10S3"], "media": [{"kind": "img", "src": "animations/chapter10/source/10.3-p3-Im3.png", "alt": "Supplied section 10.3 course figure, PDF page 3", "cap": "Exploring Geology · 10.3 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.3-p5-Im6.png", "alt": "Supplied section 10.3 course figure, PDF page 5", "cap": "Exploring Geology · 10.3 · PDF p5 · original source figure, unchanged geometry"}], "sourceFigure": true});
A.match("e2-c10-standard-3-bank","c10-3-core","Match the complete bank to these source-supported observations or relationships. A bank term may be used more than once when two observations share the same classification.",[["Young crust, hot ridge and little cover", "New seafloor at a spreading center"], ["Cooled lithosphere below surrounding ridge elevation", "Subsiding oceanic plate"], ["Thick cover near a major river mouth", "Strong sediment supply"], ["Narrow deepest bend at a convergent boundary", "Oceanic trench"], ["Smooth sediment-covered deep floor", "Abyssal plain"]],"Compare three different maps instead of treating every color as the same measurement.",["TB10:10.3"],{"examId": "exam2", "mock": false, "topics": ["E2C10S3"], "wordBank": true, "sourceFigure": false});
