A.cards("c10s4",[{"id": "g10-4-standard", "h": "10.4 · Read the evidence and complete the explanation", "c": ["c10-4-core"], "src": ["TB10:10.4"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">From a volcanic peak to a submerged flat top</h4><ul class=\"e2-note-points\"><li>Eruptions construct a volcano; wave erosion can bevel its summit near sea level; cooling and subsidence lower the foundation after magmatism wanes. A flat-topped submerged seamount records a sequence of processes.</li><li>A hot-spot age progression is interpreted relative to the magma source. Locate the active end and compare dated volcanoes before inferring the plate-motion direction.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Compare the scale of basalt construction</h4><ul class=\"e2-note-points\"><li>An oceanic plateau is a broad elevated basaltic region, often mostly submerged. Kerguelen and Ontong Java are examples in the source.</li><li>The rising plume in the model is <mark class=\"e2-study-term\">hot solid mantle</mark>. Melting and magma supply occur nearer the lithosphere; repeated flood-basalt eruptions leave a persistent thick accumulation.</li><li>Lecture 15 slide 12 emphasizes <mark class=\"e2-study-emphasis\">plume-related flood basalts and plateau construction</mark> over millions of years. The schematic does not imply that this growth happens on a human timescale.</li></ul></section>", "examId": "exam2", "traps": ["A narrow volcanic track and a broad flood-basalt plateau record different scales of magmatism."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.4-p2-Im2.png", "alt": "Exploring Geology · 10.4 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p3-Im3.png", "alt": "Exploring Geology · 10.4 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide12.png", "alt": "In-class Lecture 15 · slide 12 · original course figure", "cap": "In-class Lecture 15 · slide 12 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p4-Im5.png", "alt": "Exploring Geology · 10.4 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p4-Im6.png", "alt": "Exploring Geology · 10.4 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p4 · original source figure, unchanged geometry"}]}]);
L.EXAM2.topics.push({"id": "E2C10S4", "ch": 10, "title": "10.4 · Hotspots, island chains, and oceanic plateaus", "sections": ["10.4"], "concepts": ["c10-4-core"], "sources": ["TB10:10.4"], "media": [{"kind": "img", "src": "assets/figures/exam-chapter10/lecture15-slide12-figures.png", "alt": "Selected original in-class Lecture 15 figures, slide 12", "cap": "In-class Lecture 15 · slide 12 · selected unchanged embedded figures; lower row left to right: plume rise, submarine flood basalt, plateau"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p3-Im4.png", "alt": "Exploring Geology · 10.4 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p2-Im2.png", "alt": "Exploring Geology · 10.4 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p3-Im3.png", "alt": "Exploring Geology · 10.4 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide12.png", "alt": "In-class Lecture 15 · slide 12 · original course figure", "cap": "In-class Lecture 15 · slide 12 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p4-Im5.png", "alt": "Exploring Geology · 10.4 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p4-Im6.png", "alt": "Exploring Geology · 10.4 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.4 · PDF p4 · original source figure, unchanged geometry"}], "standardChapter10": true});
A.mc("e2-c10-standard-4-check","c10-4-core","Which sequence best explains the flat-topped submerged seamount in the source model?",["*Volcanic growth, wave planing, then continued subsidence|These processes construct, bevel and finally lower the feature.", "Subduction, glacier cutting, then continental collision|Those are not the source stages for this seamount.", "Salt deposition, salt rising, then salt melting|That is neither the material nor the process shown.", "Reef burial, continent uplift, then trench filling|That does not match the volcanic and erosional history."],"Construction, erosion and cooling-related subsidence have different roles in the same history.",["TB10:10.4"],{"examId": "exam2", "mock": false, "topics": ["E2C10S4"]});
A.mc("e2-c10-standard-4-visual","c10-4-core","In the plateau sequence, which material interpretation preserves the source’s distinction between plume and erupted rock?",["*Hot solid mantle rises; magma later supplies basalt flows|The source explicitly distinguishes solid plume ascent from melting and eruptions.", "A liquid basalt pipe fills the entire mantle|That contradicts the stated solid-mantle plume.", "The plateau consists of seawater frozen into crust|The plateau is primarily basalt, not frozen seawater.", "Only marine sediment raises the plateau in this model|The sequence depicts immense basalt additions."],"The source plateau is built by basaltic additions over geological time.",["TB10:10.4"],{"examId": "exam2", "mock": false, "topics": ["E2C10S4"], "media": [{"kind": "img", "src": "animations/chapter10/source/10.4-p3-Im4.png", "alt": "Supplied section 10.4 course figure, PDF page 3", "cap": "Exploring Geology · 10.4 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.4-p3-Im3.png", "alt": "Supplied section 10.4 course figure, PDF page 3", "cap": "Exploring Geology · 10.4 · PDF p3 · original source figure, unchanged geometry"}], "sourceFigure": true});
A.match("e2-c10-standard-4-bank","c10-4-core","Match the complete bank to these source-supported observations or relationships. A bank term may be used more than once when two observations share the same classification.",[["Repeated eruptions build a submarine mountain", "Volcanic construction"], ["Waves bevel a summit near sea level", "Wave erosion"], ["Cooling lowers the supporting oceanic plate", "Thermal subsidence"], ["Broad thick accumulation of submarine flood basalts", "Oceanic plateau"], ["Age progression along a volcanic track", "Plate motion relative to a magma source"]],"A narrow volcanic track and a broad flood-basalt plateau record different scales of magmatism.",["TB10:10.4"],{"examId": "exam2", "mock": false, "topics": ["E2C10S4"], "wordBank": true, "sourceFigure": false});
