A.cards("c10s5",[{"id": "g10-5-standard", "h": "10.5 · Read the evidence and complete the explanation", "c": ["c10-5-core"], "src": ["TB10:10.5"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Connect slab, mantle wedge and arc crust</h4><ul class=\"e2-note-points\"><li>Heating and metamorphic reactions in the descending plate release water; water promotes mantle melting above the slab. The volcano is not simply the surface end of a liquid descending plate.</li><li>Repeated magma additions thicken the arc crust. Interactions with that growing crust can yield intermediate magmas and composite volcanoes.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Combine map view with cross section</h4><ul class=\"e2-note-points\"><li>The trench and arc can curve because subduction occurs on a sphere and the slab fits a smaller width at depth. A straight cross section cannot show the whole map-view shape.</li><li>Rollback migrates the trench and arc; extension within or behind the arc can make a back-arc basin while convergence continues at the trench.</li><li>Use examples such as the Aleutians, Marianas, Tonga and Sumatra–Java to locate the trench, arc and incoming plate. A hot-spot chain does not require that geometry.</li></ul></section>", "examId": "exam2", "traps": ["A converging boundary can coexist with extension behind its volcanic arc."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im5.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im6.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im7.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p5-Im8.png", "alt": "Exploring Geology · 10.5 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p5 · original source figure, unchanged geometry"}]}]);
L.EXAM2.topics.push({"id": "E2C10S5", "ch": 10, "title": "10.5 · Island arcs, slab rollback, and backarc basins", "sections": ["10.5"], "concepts": ["c10-5-core"], "sources": ["TB10:10.5"], "media": [{"kind": "img", "src": "animations/chapter10/source/10.5-p2-Im2.png", "alt": "Exploring Geology · 10.5 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p3-Im3.png", "alt": "Exploring Geology · 10.5 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im5.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im6.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im7.png", "alt": "Exploring Geology · 10.5 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p5-Im8.png", "alt": "Exploring Geology · 10.5 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.5 · PDF p5 · original source figure, unchanged geometry"}], "standardChapter10": true});
A.mc("e2-c10-standard-5-check","c10-5-core","How can an island arc develop more substantial, intermediate-composition crust over time in the source model?",["*Repeated magmatic additions thicken and interact with arc crust|The source links magmatism, crustal growth and magma interaction.", "Seawater is compressed directly into andesite|That is not the rock-forming mechanism.", "Every island arc begins as a thick continental shield|The model starts with ocean–ocean convergence.", "The entire slab melts into one surface lava river|Water-assisted mantle melting is different from total slab melting."],"The arc evolves through additions and interactions, rather than remaining an unchanged thin oceanic plate.",["TB10:10.5"],{"examId": "exam2", "mock": false, "topics": ["E2C10S5"]});
A.mc("e2-c10-standard-5-visual","c10-5-core","Why does the source pair a curved arc with a globe illustration?",["*The slab bends into a spherical Earth and can buckle|The source uses sphere geometry and decreasing width at depth.", "A perfectly flat plate guarantees every trench is straight|That ignores the sphere shown in the comparison.", "Ocean currents push every volcano into a semicircle|Ocean-current erosion is not the stated origin of the arc geometry.", "The curvature proves that no subduction is occurring|The curve belongs to the depicted subduction system."],"Use both map view and section to understand the three-dimensional relationship.",["TB10:10.5"],{"examId": "exam2", "mock": false, "topics": ["E2C10S5"], "media": [{"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im6.png", "alt": "Supplied section 10.5 course figure, PDF page 4", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im7.png", "alt": "Supplied section 10.5 course figure, PDF page 4", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.5-p4-Im5.png", "alt": "Supplied section 10.5 course figure, PDF page 4", "cap": "Exploring Geology · 10.5 · PDF p4 · original source figure, unchanged geometry"}], "sourceFigure": true});
