A.cards("c10s6",[{"id": "g10-6-standard", "h": "10.6 · Read the evidence and complete the explanation", "c": ["c10-6-core"], "src": ["TB10:10.6"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Several histories can put water behind an arc</h4><ul class=\"e2-note-points\"><li>The Sea of Japan records <mark class=\"e2-study-term\">historical rifting and back-arc spreading</mark>. Historical opening does not establish present-day spreading activity.</li><li>The Philippine Sea’s basins and remnant arc ridges record repeated episodes of back-arc opening. The source identifies active opening close to the Mariana arc.</li><li>The western Bering basin contains oceanic crust trapped behind an offshore-shifted subduction system; its eastern shallow region overlies continental crust.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Do not classify all small seas as oceanic spreading basins</h4><ul class=\"e2-note-points\"><li>The China Sea, Java Sea and shallow Australia–Papua New Guinea region include continental platforms. Flooded continental crust can remain shallow without a new plate boundary at every coastline.</li><li>The Gulf of California combines <mark class=\"e2-study-term\">transform faults</mark> with short spreading segments as Baja moves north relative to North America. It is a different boundary history from Japan or the Bering Sea.</li></ul></section>", "examId": "exam2", "traps": ["Back-arc spreading, trapped ocean and flooded continental shelves leave different evidence."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.6-p1-Im3.png", "alt": "Exploring Geology · 10.6 · PDF p1 · original course figure", "cap": "Exploring Geology · 10.6 · PDF p1 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.6-p3-Im4.png", "alt": "Exploring Geology · 10.6 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.6 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.6-p4-Im5.png", "alt": "Exploring Geology · 10.6 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.6 · PDF p4 · original source figure, unchanged geometry"}]}]);
