A.cards("c10s7",[{"id": "g10-7-standard", "h": "10.7 · Read the evidence and complete the explanation", "c": ["c10-7-core"], "src": ["TB10:10.7"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Identify the sea, then explain its basin</h4><ul class=\"e2-note-points\"><li>Baltic: a continental valley reshaped by glaciers and flooded by rising sea level. North Sea: continental crust thinned by extension and normal faulting.</li><li>Black Sea: a remnant basin associated with Tethys and later enclosure. The proposed catastrophic postglacial flooding is an interpretation discussed by the source, not an uncontested conclusion.</li><li>The Mediterranean includes western Cenozoic rifting and eastern remnant oceanic crust plus convergence; its regions do not share one simple origin.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Compare extension with loading</h4><ul class=\"e2-note-points\"><li>Persian Gulf: Zagros thrust loading flexes Arabia downward into a <mark class=\"e2-study-term\">foreland trough</mark>. Red Sea: Arabia separates from Africa, with continental rifting and southern seafloor spreading.</li><li>Do not infer a basin mechanism from water depth or a geographic name alone. Use crust, faults, adjoining mountains and the reconstruction.</li></ul></section>", "examId": "exam2", "traps": ["Flooding, extension, remnant ocean and flexure can all produce a sea."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.7-p1-Im3.png", "alt": "Exploring Geology · 10.7 · PDF p1 · original course figure", "cap": "Exploring Geology · 10.7 · PDF p1 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.7-p2-Im4.png", "alt": "Exploring Geology · 10.7 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.7 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.7-p2-Im5.png", "alt": "Exploring Geology · 10.7 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.7 · PDF p2 · original source figure, unchanged geometry"}]}]);
