A.cards("c10s8",[{"id": "g10-8-standard", "h": "10.8 · Read the evidence and complete the explanation", "c": ["c10-8-core"], "src": ["TB10:10.8"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Identify the carbonate landform</h4><ul class=\"e2-note-points\"><li>Fringing reefs adjoin a shoreline; barrier reefs enclose a landward lagoon; atolls form rings around lagoons. Broad carbonate platforms include more extensive shallow accumulations.</li><li>Wave erosion and reworking supply carbonate sand from reef and shell material. Clear, shallow, warm conditions support the reef communities emphasized by this section.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Track two vertical motions in Darwin’s model</h4><ul class=\"e2-note-points\"><li>The volcanic foundation sinks while the reef builds upward. A barrier reef and lagoon develop as the island shrinks; continued growth can preserve an atoll after the volcano becomes submerged.</li><li>Keeping pace with subsidence or sea-level rise is a condition, not an automatic result. The source also mentions another model involving carbonate-platform erosion.</li><li>The Great Barrier Reef, Caribbean, Bahamas, Pacific islands, East Africa, Maldives and Red Sea connect geographic examples to environmental conditions.</li></ul></section>", "examId": "exam2", "traps": ["An atoll can preserve shallow-water growth above a sinking volcanic foundation."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.8-p2-Im2.png", "alt": "Exploring Geology · 10.8 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.8-p2-Im3.png", "alt": "Exploring Geology · 10.8 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.8-p3-Im4.png", "alt": "Exploring Geology · 10.8 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.8-p3-Im5.png", "alt": "Exploring Geology · 10.8 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.8-p3-Im6.png", "alt": "Exploring Geology · 10.8 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.8-p5-Im8.png", "alt": "Exploring Geology · 10.8 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.8 · PDF p5 · original source figure, unchanged geometry"}]}]);
