A.cards("c10s9",[{"id": "g10-9-standard", "h": "10.9 · Read the evidence and complete the explanation", "c": ["c10-9-core"], "src": ["TB10:10.9"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Recognize connected features without conflating them</h4><ul class=\"e2-note-points\"><li>A shelf is a gently sloping submerged continental edge; a slope is the steeper descent; a rise is a sediment apron. A canyon cuts an erosional pathway through part of this terrain.</li><li><mark class=\"e2-study-term\">Turbidity currents</mark> mix sediment and water into a dense moving flow. Submarine landslides can retain more coherent blocks and leave irregular scars and deposits.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Explain the deposit left by the flow</h4><ul class=\"e2-note-points\"><li>As a current slows, larger grains settle before smaller grains, making a bed that fines upward. Repeated events stack separate graded beds.</li><li>A submarine fan is the spreading deposit near the slope foot and rise, rather than the canyon itself or the within-bed grain-size trend. Lecture 15 slides 4 and 6 emphasize these source-to-pathway-to-deposit connections.</li><li>An inherited narrow shelf does not, by itself, prove an active margin. Check the boundary, earthquake and volcanism evidence as in the section 10.13 investigation.</li></ul></section>", "examId": "exam2", "traps": ["Connect crustal structure, canyon erosion and sediment deposition without treating them as the same feature."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.9-p2-Im2.png", "alt": "Exploring Geology · 10.9 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.9 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide01.png", "alt": "In-class Lecture 15 · slide 1 · original course figure", "cap": "In-class Lecture 15 · slide 1 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.9-p5-Im4.png", "alt": "Exploring Geology · 10.9 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.9 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.9-p6-Im6.png", "alt": "Exploring Geology · 10.9 · PDF p6 · original course figure", "cap": "Exploring Geology · 10.9 · PDF p6 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.9-p6-Im7.png", "alt": "Exploring Geology · 10.9 · PDF p6 · original course figure", "cap": "Exploring Geology · 10.9 · PDF p6 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.9-p5-Im5.png", "alt": "Exploring Geology · 10.9 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.9 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide04.png", "alt": "In-class Lecture 15 · slide 4 · original course figure", "cap": "In-class Lecture 15 · slide 4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/L15-slide06.png", "alt": "In-class Lecture 15 · slide 6 · original course figure", "cap": "In-class Lecture 15 · slide 6 · original source figure, unchanged geometry"}]}]);
