A.cards("c10s10",[{"id": "g10-10-standard", "h": "10.10 · Read the evidence and complete the explanation", "c": ["c10-10-core"], "src": ["TB10:10.10"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Accumulate soluble minerals in a restricted basin</h4><ul class=\"e2-note-points\"><li>Evaporation concentrates brine; restricted exchange prevents the concentrated solution from immediately mixing into the open ocean. Halite, gypsum and other soluble salts can precipitate.</li><li>Repeated inflow can replenish water and dissolved components, allowing extended deposition. Tidal flats, coastal basins and narrow young seas provide source examples.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Deform the deposit after burial</h4><ul class=\"e2-note-points\"><li>Weak, relatively low-density salt can <mark class=\"e2-study-term\">flow as a solid</mark>, bend or pierce overlying strata and form domes. Weak salt layers can also aid folding and faulting; exposed salt can spread downslope as a salt glacier.</li><li>In the Gulf Coast model, buried Mesozoic salt moved upward and sideways after sediment loading. Domes, folds, faults and some seafloor bumps reflect that movement.</li><li>The Sigsbee Escarpment is tied to the front of a large subsurface salt mass in the source model. Petroleum can be trapped by associated structures; salt rising is not petroleum generation.</li></ul></section>", "examId": "exam2", "traps": ["Precipitating a salt layer and deforming it later are two different geological events."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.10-p2-Im1.png", "alt": "Exploring Geology · 10.10 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.10 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.10-p2-Im2.png", "alt": "Exploring Geology · 10.10 · PDF p2 · original course figure", "cap": "Exploring Geology · 10.10 · PDF p2 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.10-p4-Im7.png", "alt": "Exploring Geology · 10.10 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.10 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.10-p5-Im8.png", "alt": "Exploring Geology · 10.10 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.10 · PDF p5 · original source figure, unchanged geometry"}]}]);
