A.cards("c10s11",[{"id": "g10-11-standard", "h": "10.11 · Read the evidence and complete the explanation", "c": ["c10-11-core"], "src": ["TB10:10.11"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Keep opening stages and time labels separate</h4><ul class=\"e2-note-points\"><li>The source opens the <mark class=\"e2-study-term\">Central Atlantic</mark> before the South Atlantic and later northern Atlantic sector. Continental rifting can precede full seafloor spreading.</li><li>The reconstruction also shows India separating from Gondwana and later approaching Asia, with much of Tethys consumed during convergence. Each panel is a world reconstruction, not half a globe.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Account for creation and destruction</h4><ul class=\"e2-note-points\"><li>Spreading creates lithosphere; subduction consumes it. An expanding ocean does not imply that Earth as a whole expands.</li><li>The source’s Atlantic–Pacific contrast is a basin-scale trend. Do not turn it into a claim that no subduction exists anywhere in or near the Atlantic.</li><li>A future map depends on continuing velocities and assumptions about collisions and boundary changes. Approximate historical reconstruction landmarks and conditional forecasts have different evidential status.</li></ul></section>", "examId": "exam2", "traps": ["Follow the reconstruction through time and account for both crust creation and consumption."], "media": [{"kind": "img", "src": "animations/chapter10/source/10.11-p3-Im3.png", "alt": "Exploring Geology · 10.11 · PDF p3 · original course figure", "cap": "Exploring Geology · 10.11 · PDF p3 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.11-p4-Im4.png", "alt": "Exploring Geology · 10.11 · PDF p4 · original course figure", "cap": "Exploring Geology · 10.11 · PDF p4 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.11-p5-Im5.png", "alt": "Exploring Geology · 10.11 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.11 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.11-p5-Im6.png", "alt": "Exploring Geology · 10.11 · PDF p5 · original course figure", "cap": "Exploring Geology · 10.11 · PDF p5 · original source figure, unchanged geometry"}, {"kind": "img", "src": "animations/chapter10/source/10.11-p6-Im8.png", "alt": "Exploring Geology · 10.11 · PDF p6 · original course figure", "cap": "Exploring Geology · 10.11 · PDF p6 · original source figure, unchanged geometry"}]}]);
